<script lang="ts">import { resolveConversationSide,type BubbleSize,type BubbleVariant,type ConversationSide } from '@fex-design/core/bubble/types';import {bubbleClassName} from '@fex-design/styles/bubble';import{cn}from'@fex/utils';import{getContext,setContext,type Snippet}from'svelte';import type{HTMLAttributes}from'svelte/elements';import{bubbleContextKey,messageSideContextKey,type BubbleContextValue}from'./context';interface Props extends HTMLAttributes<HTMLDivElement>{side?:ConversationSide;variant?:BubbleVariant;size?:BubbleSize;children?:Snippet}let{side:sideProp,variant='soft',size='md',class:className,children,...rest}:Props=$props();const inherited=getContext<(()=>ConversationSide)|undefined>(messageSideContextKey);let side=$derived(resolveConversationSide(sideProp,inherited?.()));setContext<BubbleContextValue>(bubbleContextKey,{side:()=>side,size:()=>size,variant:()=>variant})</script>
<div {...rest} data-slot="bubble" data-side={side} data-variant={variant} data-size={size} class={cn(bubbleClassName({size}),className)}>{@render children?.()}</div>
